# ============================================================================
# Lambda: api_public_create_lead
# REQ-LEADS-CONTACT-PUB-001: Submit contact inquiry
# ============================================================================

module "create_lead_lambda" {
  source = "git::https://github.com/Comecacahuates/terraform-aws-modules.git//lambda/go?ref=v1.3.1"

  function_name = "sicadcam-${var.environment}-leads-api-create-lead"
  source_file   = "${local.lambda_packages_dir}/leads_api_create_lead.zip"

  memory_size        = var.lambda_config.memory_size
  timeout            = var.lambda_config.timeout
  log_retention_days = var.lambda_config.log_retention_days

  environment_variables = {
    ENVIRONMENT   = var.environment
    TABLE_NAME    = var.dynamodb_table.name
    SNS_TOPIC_ARN = module.lead_notifications.topic_arn
  }

  policy_statements = [
    {
      Action   = ["dynamodb:PutItem"]
      Resource = [var.dynamodb_table.arn]
    },
    {
      Action   = ["sns:Publish"]
      Resource = [module.lead_notifications.topic_arn]
    }
  ]

  tags = local.common_tags
}

# ----------------------------------------------------------------------------
# API Gateway Validation Schema
# ----------------------------------------------------------------------------

locals {
  create_lead_validation_schema = jsonencode({
    type     = "object"
    required = ["interest", "name", "email", "message"]
    properties = {
      interest = {
        type = "string"
        enum = ["software", "fabrication", "training", "general"]
      }
      name = {
        type      = "string"
        minLength = 1
        maxLength = 100
      }
      email = {
        type    = "string"
        pattern = "^[^@]+@[^@]+\\.[^@]+$"
      }
      phone = {
        type      = "string"
        maxLength = 20
      }
      message = {
        type      = "string"
        minLength = 10
        maxLength = 1000
      }
      source = {
        type      = "string"
        maxLength = 200
      }
      files = {
        type     = "array"
        maxItems = 5
        items = {
          type      = "string"
          maxLength = 200
        }
      }
      details = {
        type = "object"
      }
    }
  })
}

