# ============================================================================
# Lambda: api_admin_create_course
# REQ-COURSES-SCHED-ADMIN-001: Create course
# ============================================================================

module "create_course_lambda" {
  source = "git::https://github.com/Comecacahuates/terraform-aws-modules.git//lambda/go?ref=v1.3.1"

  function_name = "sicadcam-${var.environment}-courses-api-create-course"
  source_file   = "${local.lambda_packages_dir}/courses_api_create_course.zip"

  memory_size = 128
  timeout     = 10

  environment_variables = {
    ENVIRONMENT = var.environment
    TABLE_NAME  = var.dynamodb_table.name
  }

  policy_statements = [
    {
      Action = [
        "dynamodb:PutItem"
      ]
      Resource = [
        var.dynamodb_table.arn
      ]
    }
  ]

  tags = local.common_tags
}

# ----------------------------------------------------------------------------
# API Gateway Validation Schema
# ----------------------------------------------------------------------------

locals {
  create_course_validation_schema = jsonencode({
    type     = "object"
    required = ["title", "description", "base_price", "max_participants", "sessions"]
    properties = {
      title = {
        type      = "string"
        minLength = 1
        maxLength = 200
      }
      description = {
        type      = "string"
        minLength = 10
        maxLength = 2000
      }
      base_price = {
        type    = "number"
        minimum = 0
      }
      max_participants = {
        type    = "integer"
        minimum = 1
        maximum = 50
      }
      sessions = {
        type     = "array"
        minItems = 1
        maxItems = 20
        items = {
          type     = "object"
          required = ["session_number", "date", "start_time", "end_time", "location"]
          properties = {
            session_number = {
              type    = "integer"
              minimum = 1
            }
            date = {
              type    = "string"
              pattern = "^\\d{4}-\\d{2}-\\d{2}$"
            }
            start_time = {
              type    = "string"
              pattern = "^\\d{2}:\\d{2}$"
            }
            end_time = {
              type    = "string"
              pattern = "^\\d{2}:\\d{2}$"
            }
            location = {
              type      = "string"
              minLength = 1
              maxLength = 500
            }
          }
        }
      }
    }
  })
}

