resource "aws_api_gateway_rest_api" "admin" {
  name        = "sicadcam-${var.environment}-admin-api"
  description = "Admin API for SICADCAM administrative operations"

  endpoint_configuration {
    types = ["REGIONAL"]
  }

  tags = local.common_tags
}

resource "aws_api_gateway_deployment" "admin" {
  rest_api_id = aws_api_gateway_rest_api.admin.id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.leads.id,
      aws_api_gateway_resource.courses.id,
      module.leads_cors.method_id,
      module.create_lead.method_id,
      module.list_leads_admin.method_id,
      module.courses_cors.method_id,
      module.create_course.method_id,
      module.list_courses.method_id,
      module.get_course.method_id,
      var.lambda_api_create_lead.invoke_arn,
      var.lambda_api_list_leads_admin.invoke_arn,
      var.lambda_api_create_course.invoke_arn,
      var.lambda_api_list_courses_admin.invoke_arn,
      var.lambda_api_get_course_admin.invoke_arn,
      aws_api_gateway_resource.course_publish.id,
      module.course_publish_cors.method_id,
      module.publish_course.method_id,
      var.lambda_api_publish_course.invoke_arn,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }

  depends_on = [
    module.leads_cors,
    module.create_lead,
    module.list_leads_admin,
    module.courses_cors,
    module.create_course,
    module.list_courses,
    module.get_course,
    module.course_publish_cors,
    module.publish_course
  ]
}

resource "aws_api_gateway_stage" "admin" {
  deployment_id = aws_api_gateway_deployment.admin.id
  rest_api_id   = aws_api_gateway_rest_api.admin.id
  stage_name    = var.environment

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api_logs.arn
    format = jsonencode({
      requestId      = "$context.requestId"
      ip             = "$context.identity.sourceIp"
      requestTime    = "$context.requestTime"
      httpMethod     = "$context.httpMethod"
      resourcePath   = "$context.resourcePath"
      status         = "$context.status"
      protocol       = "$context.protocol"
      responseLength = "$context.responseLength"
    })
  }

  tags = local.common_tags
}

resource "aws_cloudwatch_log_group" "api_logs" {
  name              = "/aws/apigateway/sicadcam-${var.environment}-admin"
  retention_in_days = var.environment == "production" ? 90 : 14

  tags = local.common_tags
}

locals {
  environment         = "staging"
  region              = "us-east-1"
  cors_allowed_origin = "https://sicadcam-website.netlify.app"
}

data "terraform_remote_state" "leads" {
  backend = "s3"
  config = {
    bucket = "comecacahuates-terraform-state-staging"
    key    = "sicadcam/staging/bounded_contexts/leads/application/terraform.tfstate"
    region = local.region
  }
}

data "terraform_remote_state" "courses" {
  backend = "s3"
  config = {
    bucket = "comecacahuates-terraform-state-staging"
    key    = "sicadcam/staging/bounded_contexts/courses/application/terraform.tfstate"
    region = local.region
  }
}

data "terraform_remote_state" "monitoring" {
  backend = "s3"
  config = {
    bucket = "comecacahuates-terraform-state-staging"
    key    = "sicadcam/staging/monitoring/terraform.tfstate"
    region = local.region
  }
}

module "public_api" {
  source      = "../../../../modules/apis/public"
  environment = local.environment
  region      = local.region

  lambda_api_create_lead         = data.terraform_remote_state.leads.outputs.lambda_api_create_lead
  lambda_api_list_courses_public = data.terraform_remote_state.courses.outputs.lambda_api_list_courses_public

  cors_allowed_origin = local.cors_allowed_origin
  alert_topic         = data.terraform_remote_state.monitoring.outputs.alert_topic

  # Usage plan - moderate for staging
  usage_plan = {
    burst_limit  = 10
    rate_limit   = 5
    quota_limit  = 500
    quota_period = "DAY"
  }
}

