# ============================================================================
# Lambda: event_payment_completed_to_confirm_enrollment
# REQ-COURSES-ENROLL-PUB-002: Confirm enrollment after payment
# ============================================================================

module "event_payment_completed_lambda" {
  source = "git::https://github.com/Comecacahuates/terraform-aws-modules.git//lambda/go?ref=v1.3.1"

  function_name = "sicadcam-${var.environment}-courses-event-payment-completed"
  source_file   = "${local.lambda_packages_dir}/courses_event_payment_completed_to_confirm_enrollment.zip"

  memory_size = 256
  timeout     = 30

  environment_variables = {
    TABLE_NAME     = var.dynamodb_table.name
    EVENT_BUS_NAME = var.event_bus_config.name
  }

  policy_statements = [
    {
      Action = [
        "dynamodb:GetItem",
        "dynamodb:PutItem"
      ]
      Resource = [
        var.dynamodb_table.arn
      ]
    },
    {
      Action = [
        "events:PutEvents"
      ]
      Resource = [
        "arn:aws:events:${var.region}:*:event-bus/${var.event_bus_config.name}"
      ]
    }
  ]

  tags = local.common_tags
}

# ----------------------------------------------------------------------------
# EventBridge Rule
# ----------------------------------------------------------------------------

resource "aws_cloudwatch_event_rule" "payment_completed" {
  name           = "sicadcam-${var.environment}-courses-payment-completed"
  description    = "Route PaymentCompleted events to enrollment confirmation"
  event_bus_name = var.event_bus_config.name

  event_pattern = jsonencode({
    source      = ["stripe.integration"]
    detail-type = ["PaymentCompleted"]
  })

  tags = local.common_tags
}

resource "aws_cloudwatch_event_target" "payment_completed" {
  rule           = aws_cloudwatch_event_rule.payment_completed.name
  event_bus_name = var.event_bus_config.name
  target_id      = "confirm-enrollment"
  arn            = module.event_payment_completed_lambda.function_arn
}

resource "aws_lambda_permission" "payment_completed" {
  statement_id  = "AllowExecutionFromEventBridge"
  action        = "lambda:InvokeFunction"
  function_name = module.event_payment_completed_lambda.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.payment_completed.arn
}

