{
  "asset_name": "aws_dynamodb_table",
  "asset_type": "resource",
  "description": "Provides a DynamoDB table resource.\n\n~> **Note:** We recommend using `lifecycle` [`ignore_changes`](https://www.terraform.io/docs/configuration/meta-arguments/lifecycle.html#ignore_changes) for `read_capacity` and/or `write_capacity` if there's [autoscaling policy](/docs/providers/aws/r/appautoscaling_policy.html) attached to the table.\n\n~> **Note:** When using [aws_dynamodb_table_replica](/docs/providers/aws/r/dynamodb_table_replica.html) with this resource, use `lifecycle` [`ignore_changes`](https://www.terraform.io/docs/configuration/meta-arguments/lifecycle.html#ignore_changes) for `replica`, _e.g._, `lifecycle { ignore_changes = [replica] }`.\n\n~> **Note:** If autoscaling creates drift for your `global_secondary_index` blocks and/or more granular `lifecycle` management for GSIs, we recommend using the new **experimental** resource [`aws_dynamodb_global_secondary_index`](https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/dynamodb_global_secondary_index).",
  "url": "https://raw.githubusercontent.com/hashicorp/terraform-provider-aws/main/website/docs/r/dynamodb_table.html.markdown",
  "example_usage": [
    {
      "title": "Basic Example",
      "code": "resource \"aws_dynamodb_table\" \"basic-dynamodb-table\" {\n  name           = \"GameScores\"\n  billing_mode   = \"PROVISIONED\"\n  read_capacity  = 20\n  write_capacity = 20\n  hash_key       = \"UserId\"\n  range_key      = \"GameTitle\"\n\n  attribute {\n    name = \"UserId\"\n    type = \"S\"\n  }\n\n  attribute {\n    name = \"GameTitle\"\n    type = \"S\"\n  }\n\n  attribute {\n    name = \"TopScore\"\n    type = \"N\"\n  }\n\n  ttl {\n    attribute_name = \"TimeToExist\"\n    enabled        = true\n  }\n\n  global_secondary_index {\n    name               = \"GameTitleIndex\"\n    hash_key           = \"GameTitle\"\n    range_key          = \"TopScore\"\n    write_capacity     = 10\n    read_capacity      = 10\n    projection_type    = \"INCLUDE\"\n    non_key_attributes = [\"UserId\"]\n  }\n\n  tags = {\n    Name        = \"dynamodb-table-1\"\n    Environment = \"production\"\n  }\n}"
    },
    {
      "title": "Basic Example containing Global Secondary Indexes using Multi-attribute keys pattern",
      "code": "resource \"aws_dynamodb_table\" \"basic-dynamodb-table\" {\n  name           = \"TournamentMatches\"\n  billing_mode   = \"PROVISIONED\"\n  read_capacity  = 20\n  write_capacity = 20\n  hash_key       = \"matchId\"\n\n  attribute {\n    name = \"matchId\"\n    type = \"S\"\n  }\n\n  attribute {\n    name = \"tournamentId\"\n    type = \"S\"\n  }\n\n  attribute {\n    name = \"region\"\n    type = \"S\"\n  }\n\n  attribute {\n    name = \"round\"\n    type = \"S\"\n  }\n\n  attribute {\n    name = \"bracket\"\n    type = \"S\"\n  }\n\n  attribute {\n    name = \"playerId\"\n    type = \"N\"\n  }\n\n  attribute {\n    name = \"matchDate\"\n    type = \"S\"\n  }\n\n  ttl {\n    attribute_name = \"TimeToExist\"\n    enabled        = true\n  }\n\n  # GSI with multiple HASH keys and multiple RANGE keys using key_schema\n  global_secondary_index {\n    name = \"TournamentRegionIndex\"\n    key_schema {\n      attribute_name = \"tournamentId\"\n      key_type       = \"HASH\"\n    }\n    key_schema {\n      attribute_name = \"region\"\n      key_type       = \"HASH\"\n    }\n    key_schema {\n      attribute_name = \"round\"\n      key_type       = \"RANGE\"\n    }\n    key_schema {\n      attribute_name = \"bracket\"\n      key_type       = \"RANGE\"\n    }\n    key_schema {\n      attribute_name = \"matchId\"\n      key_type       = \"RANGE\"\n    }\n    write_capacity  = 10\n    read_capacity   = 10\n    projection_type = \"ALL\"\n  }\n\n  # GSI with single HASH key and multiple RANGE keys using key_schema\n  global_secondary_index {\n    name = \"PlayerMatchHistoryIndex\"\n    key_schema {\n      attribute_name = \"playerId\"\n      key_type       = \"HASH\"\n    }\n    key_schema {\n      attribute_name = \"matchDate\"\n      key_type       = \"RANGE\"\n    }\n    key_schema {\n      attribute_name = \"round\"\n      key_type       = \"RANGE\"\n    }\n    write_capacity  = 10\n    read_capacity   = 10\n    projection_type = \"ALL\"\n  }\n\n  tags = {\n    Name        = \"dynamodb-table-1\"\n    Environment = \"production\"\n  }\n}"
    },
    {
      "title": "Global Tables",
      "code": "resource \"aws_dynamodb_table\" \"example\" {\n  name             = \"example\"\n  hash_key         = \"TestTableHashKey\"\n  billing_mode     = \"PAY_PER_REQUEST\"\n  stream_enabled   = true\n  stream_view_type = \"NEW_AND_OLD_IMAGES\"\n\n  attribute {\n    name = \"TestTableHashKey\"\n    type = \"S\"\n  }\n\n  replica {\n    region_name = \"us-east-2\"\n  }\n\n  replica {\n    region_name = \"us-west-2\"\n  }\n}"
    },
    {
      "title": "Consistency mode with 3 Replicas",
      "code": "resource \"aws_dynamodb_table\" \"example\" {\n  name             = \"example\"\n  hash_key         = \"TestTableHashKey\"\n  billing_mode     = \"PAY_PER_REQUEST\"\n  stream_enabled   = true\n  stream_view_type = \"NEW_AND_OLD_IMAGES\"\n\n  attribute {\n    name = \"TestTableHashKey\"\n    type = \"S\"\n  }\n\n  replica {\n    region_name      = \"us-east-2\"\n    consistency_mode = \"STRONG\"\n  }\n\n  replica {\n    region_name      = \"us-west-2\"\n    consistency_mode = \"STRONG\"\n  }\n}"
    },
    {
      "title": "Consistency Mode with 2 Replicas and Witness Region",
      "code": "resource \"aws_dynamodb_table\" \"example\" {\n  name             = \"example\"\n  hash_key         = \"TestTableHashKey\"\n  billing_mode     = \"PAY_PER_REQUEST\"\n  stream_enabled   = true\n  stream_view_type = \"NEW_AND_OLD_IMAGES\"\n\n  attribute {\n    name = \"TestTableHashKey\"\n    type = \"S\"\n  }\n\n  replica {\n    region_name      = \"us-east-2\"\n    consistency_mode = \"STRONG\"\n  }\n\n  global_table_witness {\n    region_name = \"us-west-2\"\n  }\n}"
    },
    {
      "title": "Replica Tagging",
      "code": "provider \"aws\" {\n  region = \"us-west-2\"\n}\n\nprovider \"awsalternate\" {\n  region = \"us-east-1\"\n}\n\nprovider \"awsthird\" {\n  region = \"us-east-2\"\n}\n\ndata \"aws_region\" \"current\" {}\n\ndata \"aws_region\" \"alternate\" {\n  provider = \"awsalternate\"\n}\n\ndata \"aws_region\" \"third\" {\n  provider = \"awsthird\"\n}\n\nresource \"aws_dynamodb_table\" \"example\" {\n  billing_mode     = \"PAY_PER_REQUEST\"\n  hash_key         = \"TestTableHashKey\"\n  name             = \"example-13281\"\n  stream_enabled   = true\n  stream_view_type = \"NEW_AND_OLD_IMAGES\"\n\n  attribute {\n    name = \"TestTableHashKey\"\n    type = \"S\"\n  }\n\n  replica {\n    region_name = data.aws_region.alternate.name\n  }\n\n  replica {\n    region_name    = data.aws_region.third.name\n    propagate_tags = true\n  }\n\n  tags = {\n    Architect = \"Eleanor\"\n    Zone      = \"SW\"\n  }\n}\n\nresource \"aws_dynamodb_tag\" \"example\" {\n  resource_arn = replace(aws_dynamodb_table.example.arn, data.aws_region.current.region, data.aws_region.alternate.name)\n  key          = \"Architect\"\n  value        = \"Gigi\"\n}"
    }
  ],
